    out: list[tuple[int, int]] = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            seen[y][x] = True
            color = int(f[y, x])
            if color == bg:
                continue
            cells = [(y, x)]
            stack = [(y, x)]
