def paint_core(
    current_frame: Any,
    transitions: list[dict[str, Any]],
    act: Callable[..., None],
    trace: list[str] | None = None,
) -> None:
    """Paint/flood core: dynamically infer background and fill colors to 
    handle levels where background is not 0."""
    frame = np.asarray(current_frame)

    # 1. Dynamically infer background color
    # The background is usually the most common color in the frame, 
    # or the color that is being replaced in transitions.
    if transitions:
        # Look at the most recent successful click to see what was replaced
        last_t = transitions[-1]
        if last_t.get("xy") is not None:
            before = np.asarray(last_t["before"])
            after = np.asarray(last_t["after"])
            diff = before != after
            if diff.any():
                # The most common 'before' color among changed cells is likely the background
                vals, counts = np.unique(before[diff], return_counts=True)
                bg_color = int(vals[counts.argmax()])
            else:
                bg_color = _BACKGROUND
        else:
            bg_color = _BACKGROUND
    else:
        # Fallback to most common color in frame
        vals, counts = np.unique(frame, return_counts=True)
        bg_color = int(vals[counts.argmax()])

    # 2. Infer fill color based on the detected background
    fill = _infer_fill_color(transitions, background=bg_color)

    if fill < 0:
        if trace is not None:
            trace.append(f"fill unconfirmed (bg={bg_color}) -> probe")
        clicks = paint_plan(frame, background=bg_color, max_clicks=1, trace=trace)
    else:
        if trace is not None:
            trace.append(f"bg={bg_color}, fill={fill} -> fill regions")
        clicks = paint_plan(frame, background=bg_color, trace=trace)

    for (x, y) in clicks:
